class Solution {
public:
    vector<int> countPrefixOccurences(string s) {
        int n = s.size();

        vector<int> z(n, 0);
        int l = 0, r = 0;

        // Create Z-array
        for (int i = 1; i < n; i++) {

            if (i <= r) {
                z[i] = min(r - i + 1, z[i - l]);
            }

            while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
                z[i]++;
            }

            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }

        // Count occurrences
        vector<int> count(n + 1, 0);

        for (int i = 1; i < n; i++) {
            count[z[i]]++;
        }

        // Suffix sum
        for (int i = n - 1; i >= 1; i--) {
            count[i] += count[i + 1];
        }

        // Prepare answer
        vector<int> ans(n);

        for (int i = 1; i <= n; i++) {
            ans[i - 1] = count[i] + 1;
        }

        return ans;
    }
};
