        String t = "";
        for(int i = 0; i < s.length(); i++) {
            t += s.charAt(i);
            int count = 0;
            for(int j = 0; j <= s.length() - t.length(); j++) {
                int k;
                for(k = 0; k < t.length(); k++) {
                    if(t.charAt(k) != s.charAt(j + k)) {
                        break;
                    }
                }
                if(k == t.length()) {
                    count++;
                }
            }
            list.add(count);
        }
        return list;
    }
}



